const compiled = ts.transpileModule(source, {
  compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 }
}).outputText;
writeFileSync(new URL('../../App/Resources/frontend/writers-catalog.js', import.meta.url),
  '// Generated by Website/scripts/build-native-writers.mjs\n' +
  '(function(scope){const exports={};\n' + compiled +
  '\nscope.LEARNED_MEDIA_WRITERS=exports.WRITERS_SEED;})(globalThis);\n');
